using System;using System.IO;using UnityEngine;using UnityEditor;
public static class SharedSystemInstall {
 public static void Run(){var p=AssetDatabase.LoadAssetAtPath<CombatV01Profile>("Assets/Shioka/調整Data/共通System/CombatTestV01.asset");if(p.guard==null)p.guard=Make<GuardSystemTuning>("Guard");if(p.tg==null)p.tg=Make<TGSystemTuning>("TG");if(p.formula==null)p.formula=Make<CombatFormulaTuning>("Combat");if(!p.Validate(out var error))throw new Exception(error);EditorUtility.SetDirty(p);AssetDatabase.SaveAssetIfDirty(p);Verify();}
 static T Make<T>(string name)where T:ScriptableObject{string path="Assets/Shioka/調整Data/共通System/"+name+".asset";if(AssetDatabase.LoadMainAssetAtPath(path)!=null)throw new Exception("Refuse overwrite "+path);var value=ScriptableObject.CreateInstance<T>();AssetDatabase.CreateAsset(value,path);return value;}
 public static void Verify(){var p=AssetDatabase.LoadAssetAtPath<CombatV01Profile>("Assets/Shioka/調整Data/共通System/CombatTestV01.asset");int count=0;foreach(double a in new[]{0d,180,200,200.1,260,360,460})foreach(double d in new[]{0d,100,180})foreach(double ta in new[]{-200d,0,100,200})foreach(double td in new[]{-100d,0,100})foreach(bool guard in new[]{false,true}){var original=CombatV01Formula.Resolve(a,d,ta,td,guard,true,10);var adopted=CombatV01Formula.Resolve(a,d,ta,td,guard,true,10,tuning:p);if(JsonUtility.ToJson(original)!=JsonUtility.ToJson(adopted))throw new Exception("Default values changed");count++;}foreach(bool continuous in new[]{false,true})for(int age=-1;age<35;age++)if(CombatV01Formula.JGReduction(age,continuous)!=CombatV01Formula.JGReduction(age,continuous,p))throw new Exception("JG changed");var test=ScriptableObject.CreateInstance<TGSystemTuning>();test.values.positiveDivisor=0;if(test.Valid)throw new Exception("Invalid divisor accepted");UnityEngine.Object.DestroyImmediate(test);File.WriteAllText("Temp/shared-system-checks.txt",count+" exact default-contact comparisons +72 JG boundaries PASS; invalid divisor rejected");Debug.Log("SHARED_SYSTEM "+count+" exact comparisons +72 JG boundaries passed");}
}
